function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a1f14', W='#8b5a2b', WL='#c48a4a', Stone='#6b6358';
  px(0,0,32,32,Stone);
  px(10,0,12,32,O);
  px(11,1,10,30,W);
  px(11,1,10,1,WL);
  px(11,14,10,1,O);
}
